import { countryCodes, type CountryCode } from '../../icons/country-names';
import './CountryIcon.css';

/* The Figma "Country icons" (src/icons/country, generated by `npm run icons`). Not inlined into the bundle:
   the page loads only the flags it shows. */
const files = import.meta.glob<string>('../../icons/country/*.svg', { eager: true, query: '?no-inline', import: 'default' });

export { countryCodes, type CountryCode };

export type CountryIconProps = {
  /** Figma name: the country code in lower case, such as `ua`. Duplicates in Figma are `bq-2`, `cd-2`. */
  code: CountryCode;
  /** Size in px. The guidelines use 20 and 24, matched to the component and text size. */
  size?: 20 | 24;
  /** Accessible name, such as "Ukraine". Leave it out when the country is written next to the flag. */
  label?: string;
  className?: string;
};

/** A round country flag (Figma "Country icon"), for countries, regions and locale selection. */
export function CountryIcon({ code, size = 24, label, className = '' }: CountryIconProps) {
  return (
    <img
      className={`grg-country-icon ${className}`}
      src={files[`../../icons/country/${code}.svg`]}
      width={size}
      height={size}
      alt={label ?? ''}
      loading="lazy"
      decoding="async"
    />
  );
}
